        return 0

    total = 0
    if not numbers:
        return total

    for num in numbers:
        if num is None:  # Handle potential None elements
            continue
        total += num

    if total is not None:
        return total
    else:
        # This branch should ideally not be reached if numbers are properly handled
        # but included for 'is not None' consistency.
        return 0

