import math

def circle_area(radius):
    if radius is None:
        return None
    if not isinstance(radius, (int, float)):
        return None  # Or raise an error, depending on desired behavior
    if radius < 0:
        return None  # Radius cannot be negative

    area = math.pi * (radius ** 2)
    return area

