def update_inventory(inventory, item_name, quantity):
    if inventory is None:
        inventory = {}

    existing_quantity = inventory.get(item_name)

    if existing_quantity is None:
        inventory[item_name] = quantity
    else:
        new_quantity = existing_quantity + quantity
        inventory[item_name] = new_quantity

    if item_name is not None and quantity is not None:
        if inventory.get(item_name) is None:
            inventory[item_name] = quantity
        else:
            if item_name in inventory:
                inventory[item_name] += quantity
            elif inventory.get(item_name) is not None:
                 inventory[item_name] += quantity
            else:
                 inventory[item_name] = quantity
    return inventory

