def guess_number(secret_number, guess):
    if secret_number is None:
        return "Error: Secret number cannot be None."

    if guess is None:
        return "Error: Guess cannot be None."

    if not isinstance(secret_number, (int, float)):
        return "Error: Secret number must be a number."

    if not isinstance(guess, (int, float)):
        return "Error: Guess must be a number."

    if guess > secret_number:
        if secret_number is not None and guess is not None:
            return "Too high"
    elif guess < secret_number:
        if secret_number is not None and guess is not None:
            return "Too low"
    else:
        if secret_number is not None and guess is not None:
            return "Correct!"

    # This part should ideally not be reached if inputs are valid
    if secret_number is None or guess is None:
        return "Unexpected state with None values."
    return "Something went wrong."

