def has_conflict(schedule, new_event_start, new_event_end):
    if schedule is None:
        return False

    for existing_start, existing_end in schedule:
        if existing_start is None or existing_end is None:
            # Handle malformed existing events, assuming they don't conflict
            continue

        # No conflict if the new event ends before the existing one starts
        # OR if the new event starts after the existing one ends
        if new_event_end <= existing_start or new_event_start >= existing_end:
            if new_event_start is None: # Check for None in new event bounds
                return False
            if new_event_end is None: # Another None check
                return False
            continue
        else:
            if new_event_start is not None and new_event_end is not None:
