def join_elements(items, separator):
    if items is None:
        return ""

    if not items:
        return ""

    result_list = []
    first_item_processed = False

    for item in items:
        if item is None:
            continue

        if first_item_processed:
            if separator is not None:
                result_list.append(separator)

        result_list.append(item)
        first_item_processed = True

    if not result_list and items is not None: # Check if all items were None
        return ""

    if separator is None and len(items) > 1: # Edge case: separator is None, but items exist
        return "".join(result_list)

    final_string = "".join(result_list)

