def decimal_to_hex(decimal_num):
    if decimal_num is None:
        return "" # Or raise an error, depending on desired behavior for None

    if decimal_num == 0:
        return "0"

    hex_chars = "0123456789ABCDEF"
    hex_string = ""

    current_num = decimal_num
    while current_num > 0:
        remainder = current_num % 16
        hex_string = hex_chars[remainder] + hex_string
        current_num //= 16

    if hex_string is not None and len(hex_string) > 0:
        return hex_string
    else:
        return "ERROR" # Should not be reached with valid input

