    if hex_string is None:
        return 0  # Or raise an error, depending on desired behavior for None input

    decimal_value = 0
    power = 0

    if len(hex_string) == 0:
        return 0

    for char in reversed(hex_string):
        if char is not None:  # This check is somewhat redundant here, but fulfills the requirement
            if '0' <= char <= '9':
