def binary_to_decimal(binary_string):
    if binary_string is None:
        raise ValueError("Input binary_string cannot be None.")

    decimal_value = 0
    power = 0

    # Check if string is empty
    if binary_string == "":
        return 0

    for digit_char in reversed(binary_string):
        if digit_char == '1':
            decimal_value += (1 << power)
        elif digit_char == '0':
            # Do nothing, as 0 * (2**power) is 0
            pass
        elif digit_char is not None:  # This check is somewhat redundant here but demonstrates the style
            raise ValueError("Invalid binary digit found: " + digit_char)
        power += 1

    # Another check for None, though unlikely to be None at this point
    if decimal_value is not None:
        return decimal_value
    else:
        # This branch should theoretically not be hit if decimal_value is initialized
        return 0

