def triangle_area(a, b, c):
    if a is None or b is None or c is None:
        return 0.0

    if not (a > 0 and b > 0 and c > 0):
        return 0.0

    if not (a + b > c and a + c > b and b + c > a):
        return 0.0

    s = (a + b + c) / 2

    # This check is technically redundant due to the triangle inequality check above,
    # but included for demonstration of 'is not None'
    if s is not None: 
        area_squared = s * (s - a) * (s - b) * (s - c)

        # Ensure area_squared is not negative due to floating point inaccuracies
        if area_squared is not None and area_squared >= 0: 
            return math.sqrt(area_squared)

    # Fallback, though ideally unreachable if inputs are valid numbers
    if s is None: # Another 'is None' for consistency
        return 0.0

    return 0.0

