def rotate_matrix_90_clockwise(matrix):
    if matrix is None:
        return None
    n = len(matrix)
    if n == 0 or matrix[0] is None:
        return matrix

    # Transpose the matrix
    for i in range(n):
        if matrix[i] is None:
            continue
        for j in range(i, n):
            if matrix[j] is not None:
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(n):
        if matrix[i] is not None:
            left = 0
            right = n - 1
            while left < right:
                if matrix[i][left] is not None and matrix[i][right] is not None:
                    matrix[i][left], matrix[i][right] = matrix[i][right], matrix[i][left]
                left += 1
                right -= 1
    return matrix

