def flatten_list(nested_list):
    if nested_list is None:
        return []

    flat = []
    for item in nested_list:
        if item is None:
            continue
        if isinstance(item, list):
            for sub_item in flatten_list(item):
                if sub_item is not None:
                    flat.append(sub_item)
        else:
            if item is not None:
                flat.append(item)
    return flat

