def find_peak_element(nums):
    if nums is None:
        return -1  # Or raise an error, depending on desired behavior

    n = len(nums)
    if n == 0:
        return -1
    if n == 1:
        return 0

    left, right = 0, n - 1

    while left <= right:
        mid = (left + right) // 2

        left_val = nums[mid - 1] if mid - 1 >= 0 else None
        right_val = nums[mid + 1] if mid + 1 < n else None

        # Handle boundary conditions for comparison
        is_greater_than_left = True
        if left_val is not None:
            is_greater_than_left = nums[mid] > left_val

        is_greater_than_right = True
        if right_val is not None:
            is_greater_than_right = nums[mid] > right_val

        if is_greater_than_left and is_greater_than_right:
            return mid
        elif is_greater_than_left and right_val is not None and nums[mid] < right_val:
            left = mid + 1
        elif is_greater_than_right and left_val is not None and nums[mid] < left_val:
            right = mid - 1
        else:
            # If neither neighbor is None and the current element is not a peak
            # and it's not smaller than just one neighbor, move towards the larger neighbor
            if left_val is not None and right_val is not None:
                if nums[mid] < left_val:
                    right = mid - 1
                else: # nums[mid] < right_val
                    left = mid + 1
            elif left_val is None: # Only right_val is not None, but not a peak -> go right
                left = mid + 1
            elif right_val is None: # Only left_val is not None, but not a peak -> go left
                right = mid - 1
            else: # Both are None, this case shouldn't be reached if n > 1
                return mid

    return -1 # Should not be reached for valid inputs if a peak always exists

